class MetaMaskIntegration{constructor(){this.ethereum=window.ethereum,this.chainId="0xaa36a7",this.accountLevelsAddress="0xC6849b102241A181030c61bb3bF2808Eb2921D58",this.etherDeltaAddress="0x07ef7942554a62F98eFC96a464c005D2e0b21873"}async initialize(){if(!this.ethereum)throw new Error("Please install MetaMask!");try{const e=await this.ethereum.request({method:"eth_requestAccounts"});return await this.switchToSepolia(),e[0]}catch(e){throw console.error("User denied account access or network switch failed"),e}}async switchToSepolia(){try{await this.ethereum.request({method:"wallet_switchEthereumChain",params:[{chainId:this.chainId}]})}catch(e){if(4902!==e.code)throw e;await this.ethereum.request({method:"wallet_addEthereumChain",params:[{chainId:this.chainId,chainName:"Sepolia",nativeCurrency:{name:"ETH",symbol:"ETH",decimals:18},rpcUrls:["https://sepolia.infura.io/v3/edb21febc56648be87babedccd5fe088"],blockExplorerUrls:["https://sepolia.etherscan.io"]}]})}}async signMessage(e){try{const t=await this.ethereum.request({method:"eth_accounts"});return await this.ethereum.request({method:"personal_sign",params:[e,t[0]]})}catch(e){throw console.error("Error signing message:",e),e}}onAccountsChanged(e){this.ethereum.on("accountsChanged",e)}onChainChanged(e){this.ethereum.on("chainChanged",e)}async getChainId(){return await this.ethereum.request({method:"eth_chainId"})}}window.MetaMaskIntegration=MetaMaskIntegration;